        <Button key="preview" label="预览" onPress={() => void openPane($)} />
        <Button key="send" label="发出" variant="primary" onPress={() => void send($)} />
        <Button key="clear" label="清空" dimColor onPress={() => void clearBasket($)} />
      </Box>
